import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"模拟链接","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"zh/qgc-dev-guide/tools/mock_link.md","filePath":"zh/qgc-dev-guide/tools/mock_link.md"}`),a={name:`zh/qgc-dev-guide/tools/mock_link.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="模拟链接" tabindex="-1">模拟链接 <a class="header-anchor" href="#模拟链接" aria-label="Permalink to “模拟链接”">​</a></h1><p>Mock Link允许您在QGroundControl调试版本中创建和停止指向多个模拟（模拟）载具的链接。</p><p>模拟不支持飞行，但允许轻松测试：</p><ul><li>任务上传/下载</li><li>查看和更改参数</li><li>测试大多数设置页面</li><li>多个载具用户界面</li></ul><p>对于任务上载/下载的单元测试错误情况尤其有用。</p><h2 id="使用mock-link" tabindex="-1">使用Mock Link <a class="header-anchor" href="#使用mock-link" aria-label="Permalink to “使用Mock Link”">​</a></h2><p>为了使用Mock Link：</p><ol><li><p>Create a Debug build by <a href="./../getting_started/">building the source</a>.</p></li><li><p>Access <em>Mock Link</em> by selecting the <em>Application Settings</em> icon in the top toolbar and then <strong>Mock Link</strong> in the sidebar.</p></li><li><p>Choose the <strong>Vehicle Type</strong> (PX4, ArduPilot Copter/Plane/Sub/Rover, or Generic) and <strong>Home Location</strong>, and optionally a served video stream and simulated camera, gimbal, proximity sensors or ADS-B vehicles.</p></li><li><p>Click <strong>Start MockLink</strong> to create a vehicle link with those settings.</p><ul><li>Each time you click the button a new connection will be created.</li><li>当存在多个连接时，将显示多载具UI。</li></ul></li><li><p>Click <strong>Stop One MockLink</strong> to stop the currently active vehicle.</p></li></ol><p>然后使用模拟链接或多或少与使用任何其他载具相同，只是模拟不允许飞行。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>To test with a vehicle that flies, use a SITL simulator. <a href="https://github.com/mavlink/qgroundcontrol/tree/master/tools/simulation" target="_blank" rel="noreferrer"><code>tools/simulation</code></a> in the source tree has a lightweight MAVLink vehicle simulator and an ArduCopter SITL launcher.</p></div>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};